# EN: Curate the sample content only; all theme CSS, layouts and artwork come from the native exporter.
# HR: Oblikuje samo ogledni sadržaj; CSS, raspored i slike tema dolaze iz izvornog izvoznika.
from pathlib import Path
import json,re,html,sys
root=Path(sys.argv[1]).resolve()
entries=json.loads((root/'catalog.json').read_text())
catalog={'themes':[{'id':t['id'],'name':t['label'].get('en',t['id']),'description':{'hr':'Izgled za vašu Simbiozu. Sve boje, raspored i slike mogu se prilagoditi.'},'style':'modern'} for t in entries]}
style_names={'sports':'Sport','education':'Škola','preschool':'Vrtić','cinema':'Film','art':'Umjetnost','outdoors':'Priroda','modern':'Moderna','editorial':'Urednička','gaming':'Gaming','retro':'Retro','nature':'Prirodna','coastal':'Morska','technical':'Tehnička','calm':'Nježna','creative':'Kreativna','blog':'Blog','elegant':'Elegantna'}
for entry in catalog['themes']:
    p=root/'preview'/entry['id']/'index.html';s=p.read_text();name=html.escape(entry['name']);desc=html.escape(entry['description']['hr'])
    s=s.replace('Upute za temu',name).replace('Theme guidelines',name).replace('Theme guide',name).replace('Samostalni offline primjer odabrane teme.',desc.split('. ')[0]+'.').replace('HeartPhrame theme package','Simbioza · '+style_names[entry['style']])
    main=f'''<div class="row g-4"><div class="col-lg-8"><article class="card hph-content-card mb-4"><div class="card-body p-4"><div class="d-flex align-items-center gap-2 mb-3"><span class="badge bg-primary">Dobro došli</span><span class="small text-muted">Prostor za vaš tim</span></div><h2 class="mb-3">Mjesto za ideje koje rastu.</h2><p class="mb-4">Povežite stranice, znanje, događanja i ankete u zajedničko okruženje. Ovdje svaka ideja može postati nešto više.</p><div class="d-flex flex-wrap gap-2"><a class="btn btn-primary" href="components.html">Istraži mogućnosti</a><a class="btn btn-outline-secondary" href="layout.html">Pogledaj raspored</a></div></div></article><div class="row g-4"><div class="col-md-6"><article class="card hph-content-card h-100"><div class="card-body p-4"><span class="small text-muted">01 / ZNANJE</span><h3 class="h5 mt-2">Sve na jednom mjestu</h3><p class="mb-0">Dokumenti, upute i zajedničke bilješke koje je lako pronaći.</p></div></article></div><div class="col-md-6"><article class="card hph-content-card h-100"><div class="card-body p-4"><span class="small text-muted">02 / SURADNJA</span><h3 class="h5 mt-2">Bolje ideje, zajedno</h3><p class="mb-0">Razgovori, zadatci i povratne informacije povezuju vaš tim.</p></div></article></div></div></div><aside class="col-lg-4"><section class="card hph-sidebar-card"><div class="card-body p-4"><h2 class="h5 mb-3">U fokusu</h2><p class="small text-muted">{desc}</p><hr><div class="d-flex justify-content-between mb-3"><span>Proljetna radionica</span><span class="badge bg-success">Novo</span></div><p class="small mb-3">Podijelite iskustva i pretvorite znanje u praksu.</p><a href="secondary.html">Pročitaj više →</a></div></section></aside></div><section class="card hph-content-card mt-4"><div class="card-body p-4"><h2 class="h5">Zajednički projekti</h2><div class="table-responsive"><table class="table mb-0"><thead><tr><th scope="col">Projekt</th><th scope="col">Tim</th><th scope="col">Status</th></tr></thead><tbody><tr><td>Otvorena knjižnica</td><td>Znanje</td><td>U pripremi</td></tr><tr><td>Razgovori petkom</td><td>Zajednica</td><td>Aktivno</td></tr></tbody></table></div></div></section>'''
    translations = {'Dobro došli':'Welcome','Prostor za vaš tim':'A place for your team','Mjesto za ideje koje rastu.':'A home for ideas that grow.','Povežite stranice, znanje, događanja i ankete u zajedničko okruženje. Ovdje svaka ideja može postati nešto više.':'Bring pages, knowledge, events and surveys together. Give every idea room to grow.','Istraži mogućnosti':'Explore the features','Pogledaj raspored':'View the layout','ZNANJE':'KNOWLEDGE','Sve na jednom mjestu':'Everything in one place','Dokumenti, upute i zajedničke bilješke koje je lako pronaći.':'Documents, guides and shared notes that are easy to find.','SURADNJA':'COLLABORATION','Bolje ideje, zajedno':'Better ideas, together','Razgovori, zadatci i povratne informacije povezuju vaš tim.':'Discussions, tasks and feedback connect your team.','U fokusu':'In focus','Izgled za vašu Simbiozu. Sve boje, raspored i slike mogu se prilagoditi.':'A look for your Simbioza. Customize colours, layouts and images.','Proljetna radionica':'Spring workshop','Novo':'New','Podijelite iskustva i pretvorite znanje u praksu.':'Share your experience and put knowledge into practice.','Pročitaj više':'Read more','Zajednički projekti':'Shared projects','Projekt':'Project','Tim':'Team','Status':'Status','Otvorena knjižnica':'Open library','Znanje':'Knowledge','U pripremi':'Planning','Razgovori petkom':'Friday conversations','Zajednica':'Community','Aktivno':'Active'}
    english = main
    for source, target in translations.items():
        english = english.replace(source, target)
    main = '<div data-hph-lang="hr">' + main + '</div><div data-hph-lang="en" hidden>' + english + '</div>'
    s=re.sub(r'(<main id="main-content"[^>]*>).*?(</main>)',lambda m:m[1]+main+m[2],s,flags=re.S)
    s=s.replace('Offline demonstracijski paket HeartPhrame teme.', 'Simbioza · '+name+' · Pregled izgleda teme')
    s=s.replace('Language / Jezik','Jezik').replace('Theme / Tema','Izgled').replace('◐ Automatic / Automatski','◐ Automatski').replace('☀ Light / Svijetla','☀ Svijetla').replace('☾ Dark / Tamna','☾ Tamna')
    s=s.replace('Simbioza · Moderna', 'Simbioza').replace('Standalone offline preview of the selected theme.', 'Pages, knowledge and collaboration in one place.')
    p.write_text(s)
print('26 curated previews retain native exported CSS and local artwork.')
